CREATE TEMPORARY TABLE market_history_staging AS WITH market AS (SELECT dm_date, dm_s_symb, dm_close, dm_high, dm_low, dm_vol, MAX(dm_high) OVER fifty_two_weeks AS fiftytwoweekhigh, ARG_MAX(dm_date, CAST(dm_high * 100 AS BIGINT) * 100000000 - DATE_DIFF('DAY', CAST('1800-01-01' AS DATE), dm_date)) OVER fifty_two_weeks AS fiftytwoweekhighdate, MIN(dm_low) OVER fifty_two_weeks AS fiftytwoweeklow, ARG_MIN(dm_date, CAST(dm_low * 100 AS BIGINT) * 100000000 + DATE_DIFF('DAY', CAST('1800-01-01' AS DATE), dm_date)) OVER fifty_two_weeks AS fiftytwoweeklowdate FROM DailyMarketRaw WHERE batchid = 1 WINDOW fifty_two_weeks AS (PARTITION BY dm_s_symb ORDER BY dm_date RANGE BETWEEN INTERVAL '1 year -1 day' PRECEDING AND CURRENT ROW)), priced AS (SELECT m.*, s.SK_SecurityID, s.SK_CompanyID, s.Dividend, c.CompanyID, DATE_TRUNC('QUARTER', m.dm_date) AS quarter_start FROM market AS m JOIN DimSecurity AS s ON s.Symbol = m.dm_s_symb AND m.dm_date >= s.EffectiveDate AND m.dm_date < s.EndDate JOIN DimCompany AS c ON c.SK_CompanyID = s.SK_CompanyID), quarters AS (SELECT DISTINCT CompanyID, quarter_start FROM priced), earnings AS (SELECT q.CompanyID, q.quarter_start, SUM(f.FI_BASIC_EPS) AS eps FROM quarters AS q JOIN DimCompany AS c ON c.CompanyID = q.CompanyID JOIN Financial AS f ON f.SK_CompanyID = c.SK_CompanyID AND f.FI_QTR_START_DATE >= q.quarter_start - INTERVAL '1' YEAR AND f.FI_QTR_START_DATE < q.quarter_start GROUP BY q.CompanyID, q.quarter_start) SELECT p.*, e.eps FROM priced AS p LEFT JOIN earnings AS e ON e.CompanyID = p.CompanyID AND e.quarter_start = p.quarter_start;
INSERT INTO DImessages (MessageDateAndTime, BatchID, MessageSource, MessageText, MessageType, MessageData) SELECT CURRENT_TIMESTAMP, 1, 'FactMarketHistory', 'No earnings for company', 'Alert', CONCAT('DM_S_SYMB = ', dm_s_symb) FROM market_history_staging WHERE eps IS NULL;
INSERT INTO FactMarketHistory (SK_SecurityID, SK_CompanyID, SK_DateID, PERatio, Yield, FiftyTwoWeekHigh, SK_FiftyTwoWeekHighDate, FiftyTwoWeekLow, SK_FiftyTwoWeekLowDate, ClosePrice, DayHigh, DayLow, Volume, BatchID) SELECT m.SK_SecurityID, m.SK_CompanyID, d.SK_DateID, m.dm_close / NULLIF(m.eps, 0), m.Dividend / m.dm_close * 100, m.fiftytwoweekhigh, hd.SK_DateID, m.fiftytwoweeklow, ld.SK_DateID, m.dm_close, m.dm_high, m.dm_low, m.dm_vol, 1 FROM market_history_staging AS m JOIN DimDate AS d ON d.DateValue = m.dm_date JOIN DimDate AS hd ON hd.DateValue = m.fiftytwoweekhighdate JOIN DimDate AS ld ON ld.DateValue = m.fiftytwoweeklowdate;
